import json, itertools
from decimal import Decimal, ROUND_HALF_UP, ROUND_HALF_EVEN, ROUND_HALF_DOWN
L = json.load(open("tests/reference_totals.json"))

def compute(case, per_line, line_mode, final_mode, use_dec):
    tax = case["tax_pct"]
    def line(q,u,d):
        if use_dec:
            v = Decimal(str(q))*Decimal(str(u))*(Decimal(1)-Decimal(str(d))/Decimal(100))
        else:
            v = q*u*(1-d/100)
        if per_line:
            if use_dec:
                v = (v if isinstance(v,Decimal) else Decimal(str(v))).quantize(Decimal("0.01"), rounding=line_mode)
            else:
                v = round(v,2)
        return v
    if use_dec:
        sub = sum((line(*ln) for ln in case["lines"]), Decimal(0))
        tot = sub*(Decimal(1)+Decimal(str(tax))/Decimal(100))
        if final_mode == "floatround":
            return round(float(tot),2)
        return float(tot.quantize(Decimal("0.01"), rounding=final_mode))
    else:
        sub = sum(line(*ln) for ln in case["lines"])
        tot = sub*(1+tax/100)
        if final_mode == "floatround":
            return round(tot,2)
        return float(Decimal(str(tot)).quantize(Decimal("0.01"), rounding=final_mode))

dec_modes = [ROUND_HALF_UP, ROUND_HALF_EVEN, ROUND_HALF_DOWN]
final_modes = dec_modes + ["floatround"]
for use_dec in (True, False):
    for per_line in (True, False):
        line_modes = dec_modes if (use_dec and per_line) else [None]
        for lm in line_modes:
            for fm in final_modes:
                if not use_dec and fm in dec_modes:
                    continue  # for float arithmetic only test floatround + decimal-quantize final
                results = {n: compute(c, per_line, lm, fm, use_dec) for n,c in L.items()}
                bad = {n:(results[n], L[n]["expected_total"]) for n in L if results[n]!=L[n]["expected_total"]}
                if not bad:
                    print("WINNER:", "use_dec",use_dec,"per_line",per_line,"line_mode",lm,"final_mode",fm)
print("done")
```

