import json, itertools
from decimal import Decimal, ROUND_HALF_UP, ROUND_HALF_EVEN, ROUND_DOWN

L = json.load(open("tests/reference_totals.json"))

def rnd(x, mode, use_dec):
    if not use_dec:
        return round(x, 2)
    return float(Decimal(str(x)).quantize(Decimal("0.01"), rounding=mode))

def total(lines, tax, per_line, use_dec, mode):
    sub = 0.0
    for q,u,d in lines:
        amt = q*u*(1-d/100)
        if per_line:
            amt = rnd(amt, mode, use_dec)
        sub += amt
