for per_line in (True, False):
    for use_dec in (False, True):
        modes = [("round",None)] if not use_dec else [("HALF_UP",ROUND_HALF_UP),("HALF_EVEN",ROUND_HALF_EVEN),("DOWN",ROUND_DOWN)]
        for mname, mode in modes:
            ok = sum(1 for n,c in L.items()
                     if total([tuple(x) for x in c["lines"]], c["tax_pct"], per_line, use_dec, mode)==c["expected_total"])
