# Canonicalize a person's display name to the company house style.

_LOWERCASE_PARTICLES = {"van", "von", "de", "del", "della", "der", "di", "du", "da", "la", "ten", "ter", "bin", "al"}


def _is_initial(token):
    t = token.rstrip(".")
    return len(t) == 1 and t.isalpha()


def _cap(word):
    if not word:
        return word
    return word[0].upper() + word[1:].lower()


def canon(name):
    tokens = name.split()
    out = []
    buf = []
    for tok in tokens:
        if _is_initial(tok):
            buf.append(tok.rstrip(".").upper())
            continue
        if buf:
            out.append(".".join(buf) + ".")
            buf = []
        if tok.lower() in _LOWERCASE_PARTICLES:
            out.append(tok.lower())
        else:
            out.append(_cap(tok))
    if buf:
        out.append(".".join(buf) + ".")
    return " ".join(out)

